function Pill({children,tone='teal'}:{children:ReactNode;tone?:'teal'|'amber'|'red'|'gray'|'green'}){return <span className={`pill ${tone}`}>{children}</span>}
function Empty({icon:Icon=Package,title,subtitle}:{icon?:typeof Package;title:string;subtitle?:string}){return <div className="empty"><div className="empty-icon"><Icon size={26}/></div><h3>{title}</h3>{subtitle&&<p>{subtitle}</p>}</div>}
function Modal({children,onClose,title,large=false}:{children:ReactNode;onClose:()=>void;title:string;large?:boolean}){useEffect(()=>{const f=(e:KeyboardEvent)=>e.key==='Escape'&&onClose();window.addEventListener('keydown',f);return()=>window.removeEventListener('keydown',f)},[onClose]);return <div className="modal-backdrop" onClick={onClose}><div className={`modal ${large?'modal-lg':''}`} role="dialog" aria-modal="true" onClick={e=>e.stopPropagation()}><div className="modal-header"><h2>{title}</h2><button className="icon-btn" aria-label="Fechar" onClick={onClose}><X size={21}/></button></div><div className="modal-body">{children}</div></div></div>}
function Input({label,children,hint}:{label:string;children:ReactNode;hint?:string}){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
function Kpi({label,value,icon:Icon,sub,tone='teal'}:{label:string;value:string;icon:typeof Package;sub?:string;tone?:string}){return <div className="kpi"><div className="kpi-top"><span>{label}</span><span className={`kpi-icon ${tone}`}><Icon size={19}/></span></div><strong>{value}</strong>{sub&&<small>{sub}</small>}</div>}
function ProductVisual({p,large=false}:{p:CatalogProduct|Product;large?:boolean}){const photo=p.photo_urls?.[0];return <div className={`product-visual ${large?'large':''}`}>{photo?<img src={photo} alt={p.name}/>:<div className="product-placeholder"><Gem size={large?52:38} strokeWidth={1.2}/><span>SF</span></div>}</div>}
function formatError(err:unknown){const x=err as {message?:string;details?:string};return x?.message||'Não foi possível concluir a operação. Tente novamente.'}

